INSERT IGNORE INTO themes (title, description) VALUES     ('Java & Spring Boot', 'Développement backend, API REST, sécurité et écosystème Java.'),     ('Angular', 'Interfaces web modernes, composants, formulaires et réactivité.'),     ('DevOps', 'Automatisation, conteneurs, intégration et déploiement continus.'),     ('Architecture logicielle', 'Conception, séparation des responsabilités et maintenabilité.'),     ('Bases de données', 'Modélisation, SQL, transactions et performance des données.'),     ('Tests & Qualité', 'Tests automatisés, débogage et bonnes pratiques de qualité.');
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Construire une API REST maintenable avec Spring Boot',     CONCAT(         'Une API REST ne se résume pas à exposer quelques endpoints. Avant de coder, il est utile de définir les ressources, les contrats HTTP et les règles métier. Un contrôleur doit rester léger et déléguer les traitements à des services clairement identifiés.',         CHAR(10), CHAR(10),         'Les DTO permettent de contrôler les données entrantes et sortantes sans exposer directement les entités JPA. Ajoutez une validation explicite, des codes de statut cohérents et une gestion centralisée des exceptions.',         CHAR(10), CHAR(10),         'Enfin, des tests d’intégration sur les parcours critiques et une documentation OpenAPI rendent le service plus simple à maintenir et à faire évoluer.'     ),     t.id,     u.id,     '2026-05-05 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Java & Spring Boot' AND u.email = 'alice.martin@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Construire une API REST maintenable avec Spring Boot' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Sécuriser une application Spring avec JWT',     CONCAT(         'L’authentification par JWT permet au serveur de vérifier l’identité d’un utilisateur à chaque requête. Le jeton doit être signé avec une clé robuste, posséder une date d’expiration et être transmis uniquement sur une connexion HTTPS.',         CHAR(10), CHAR(10),         'La sécurité ne se limite pas au filtre JWT : chaque endpoint doit appliquer les autorisations adaptées au rôle ou au propriétaire de la ressource. Une validation côté frontend améliore l’expérience, mais ne remplace jamais les contrôles du backend.',         CHAR(10), CHAR(10),         'Prévoyez également le traitement des réponses 401 et 403, la rotation des secrets et des tests sur les accès refusés.'     ),     t.id,     u.id,     '2026-05-13 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Java & Spring Boot' AND u.email = 'mehdi.benali@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Sécuriser une application Spring avec JWT' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Organiser une application Angular par fonctionnalités',     CONCAT(         'Lorsque l’application grandit, ranger tous les composants dans un dossier unique devient difficile à maintenir. Une organisation par fonctionnalités regroupe pages, composants, services et modèles autour d’un même domaine métier.',         CHAR(10), CHAR(10),         'Les composants de présentation reçoivent des données et émettent des événements, tandis que les pages coordonnent la navigation et les appels aux services. Les formulaires réactifs facilitent la validation et les messages d’erreur.',         CHAR(10), CHAR(10),         'Cette séparation rend les évolutions plus lisibles et permet de tester les comportements sans dépendre de toute l’application.'     ),     t.id,     u.id,     '2026-06-05 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Angular' AND u.email = 'sophie.bernard@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Organiser une application Angular par fonctionnalités' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Signals et RxJS : choisir le bon outil',     CONCAT(         'Les signals sont pratiques pour représenter un état local qui doit être affiché automatiquement dans le template. Ils conviennent notamment aux filtres, aux sélections et aux valeurs calculées à partir d’autres états.',         CHAR(10), CHAR(10),         'RxJS reste particulièrement utile pour les flux asynchrones, les requêtes HTTP, les événements et les traitements combinés. Les deux approches ne sont pas concurrentes : elles répondent à des besoins différents.',         CHAR(10), CHAR(10),         'Pour garder un code clair, évitez de multiplier les conversions inutiles et choisissez une stratégie cohérente pour chaque fonctionnalité.'     ),     t.id,     u.id,     '2026-06-13 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Angular' AND u.email = 'ines.diallo@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Signals et RxJS : choisir le bon outil' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Dockeriser une application Java et Angular',     CONCAT(         'Un environnement reproductible réduit les écarts entre les machines des développeurs. Docker permet de construire des images pour le backend et le frontend, tandis que Docker Compose facilite le démarrage des services nécessaires, comme la base de données.',         CHAR(10), CHAR(10),         'Une bonne image utilise une étape de compilation distincte de l’exécution et n’embarque ni secrets ni fichiers inutiles. Les paramètres sensibles doivent être injectés au démarrage par des variables d’environnement.',         CHAR(10), CHAR(10),         'Avant de publier une image, vérifiez les ports, les volumes, les health checks et la gestion des journaux.'     ),     t.id,     u.id,     '2026-07-05 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'DevOps' AND u.email = 'hugo.petit@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Dockeriser une application Java et Angular' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Mettre en place une pipeline CI efficace',     CONCAT(         'Une pipeline d’intégration continue doit fournir un retour rapide sur chaque changement. Elle peut commencer par l’installation des dépendances, l’analyse statique et les tests unitaires, puis exécuter les tests d’intégration et construire les artefacts.',         CHAR(10), CHAR(10),         'Séparer les étapes permet de comprendre rapidement pourquoi un build échoue. Le cache des dépendances accélère les exécutions, mais il faut éviter de masquer des problèmes de reproductibilité.',         CHAR(10), CHAR(10),         'Une fois les vérifications stabilisées, le déploiement peut être automatisé avec des approbations adaptées aux environnements sensibles.'     ),     t.id,     u.id,     '2026-07-13 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'DevOps' AND u.email = 'lucas.moreau@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Mettre en place une pipeline CI efficace' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Comprendre l’architecture hexagonale',     CONCAT(         'L’architecture hexagonale place les règles métier au centre de l’application. Le domaine ne doit pas dépendre directement d’un framework web, d’une base de données ou d’un fournisseur de paiement.',         CHAR(10), CHAR(10),         'Les ports décrivent les interactions nécessaires au métier. Les adaptateurs fournissent les implémentations concrètes, par exemple un repository JPA ou un client HTTP externe. Cette organisation facilite le remplacement d’une technologie sans réécrire les règles métier.',         CHAR(10), CHAR(10),         'Elle demande toutefois de la discipline : pour une petite application, il faut conserver une structure proportionnée à la complexité réelle.'     ),     t.id,     u.id,     '2026-08-05 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Architecture logicielle' AND u.email = 'alice.martin@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Comprendre l’architecture hexagonale' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Responsabilités et frontières entre les couches',     CONCAT(         'Une architecture en couches est utile lorsque chaque couche possède une responsabilité précise. Le contrôleur reçoit les requêtes et produit les réponses, le service applique les règles métier et le repository gère la persistance.',         CHAR(10), CHAR(10),         'Les DTO et les mappers limitent le couplage entre l’API et le modèle de données. Les transactions doivent être définies autour d’opérations métier cohérentes plutôt qu’au hasard des appels techniques.',         CHAR(10), CHAR(10),         'Le meilleur indicateur d’une bonne séparation reste la facilité à modifier une règle sans devoir changer plusieurs parties sans rapport de l’application.'     ),     t.id,     u.id,     '2026-08-13 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Architecture logicielle' AND u.email = 'sophie.bernard@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Responsabilités et frontières entre les couches' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Bien modéliser les relations SQL',     CONCAT(         'Une base relationnelle solide commence par des entités et des contraintes clairement définies. Les clés étrangères assurent la cohérence entre les tables, tandis que les contraintes d’unicité empêchent certains doublons métier.',         CHAR(10), CHAR(10),         'Pour une relation plusieurs-à-plusieurs qui porte des informations propres, une table d’association explicite est souvent préférable. Il faut également réfléchir au comportement attendu lors des suppressions et aux colonnes réellement obligatoires.',         CHAR(10), CHAR(10),         'Un schéma bien conçu simplifie les requêtes et évite de reporter toute la validation sur le code applicatif.'     ),     t.id,     u.id,     '2026-09-05 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Bases de données' AND u.email = 'mehdi.benali@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Bien modéliser les relations SQL' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Optimiser une requête sans deviner',     CONCAT(         'Avant d’ajouter des index, commencez par mesurer les requêtes lentes et examiner leur plan d’exécution. Un index peut accélérer une recherche, mais il augmente aussi le coût des écritures et l’espace utilisé.',         CHAR(10), CHAR(10),         'Les problèmes de performance viennent parfois d’un nombre excessif de requêtes, notamment lorsqu’une relation JPA déclenche des chargements répétés. La pagination et la sélection des seules colonnes nécessaires peuvent améliorer nettement les temps de réponse.',         CHAR(10), CHAR(10),         'Chaque optimisation doit être vérifiée avec des données représentatives et des mesures comparables.'     ),     t.id,     u.id,     '2026-09-13 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Bases de données' AND u.email = 'ines.diallo@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Optimiser une requête sans deviner' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Écrire des tests qui résistent aux changements',     CONCAT(         'Un bon test décrit un comportement observable plutôt que les détails internes de son implémentation. Il prépare un contexte clair, exécute une action et vérifie un résultat précis. Les tests trop dépendants de l’ordre d’exécution deviennent rapidement fragiles.',         CHAR(10), CHAR(10),         'Les tests unitaires conviennent aux règles métier isolées. Les tests d’intégration vérifient les échanges avec les composants réels, et les tests E2E couvrent quelques parcours essentiels du point de vue de l’utilisateur.',         CHAR(10), CHAR(10),         'Un jeu de données maîtrisé et une réinitialisation fiable de l’environnement sont indispensables pour obtenir des résultats reproductibles.'     ),     t.id,     u.id,     '2026-10-05 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Tests & Qualité' AND u.email = 'lucas.moreau@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Écrire des tests qui résistent aux changements' AND existing.author_id = u.id);
INSERT INTO articles (title, content, theme_id, author_id, created_at) SELECT     'Déboguer méthodiquement une erreur full-stack',     CONCAT(         'Lorsqu’une fonctionnalité échoue, commencez par identifier la couche concernée : interface Angular, requête réseau, contrôleur Spring ou accès à la base. Les outils de développement du navigateur montrent les URL, les statuts HTTP et les corps des réponses.',         CHAR(10), CHAR(10),         'Côté Java, un point d’arrêt placé au début du service métier permet de suivre les paramètres et les branches exécutées. Les logs structurés complètent le débogueur pour les problèmes difficiles à reproduire.',         CHAR(10), CHAR(10),         'Après avoir corrigé la cause, ajoutez un test de non-régression afin d’éviter que le même défaut réapparaisse.'     ),     t.id,     u.id,     '2026-10-13 10:00:00' FROM themes t CROSS JOIN users u WHERE t.title = 'Tests & Qualité' AND u.email = 'hugo.petit@example.com' AND NOT EXISTS (SELECT 1 FROM articles existing WHERE existing.title = 'Déboguer méthodiquement une erreur full-stack' AND existing.author_id = u.id);
